tools.example:
psol = ParametricNDSolve[{y'[t] == -k y[t] + a, y[0] == 1}, y, {t, 0, 10}, {k, a}];
Plot[Evaluate[Table[y[k, 0.2][t] /. psol, {k, 0.5, 2, 0.5}]], {t, 0, 10}]
D[y[k, a][t] /. psol, k] (* sensitivity *)

ou = ItoProcess[{-theta (x - mu), sigma}, {x, 0}, t] /. {theta -> 1, mu -> 1, sigma -> 0.3};
paths = RandomFunction[ou, {0, 10, 0.01}, 5];
ListLinePlot[paths]
Mean[ou[t]]

pts = RandomReal[100, {50, 2}];
{len, order} = FindShortestTour[pts];
Graphics[{Line[pts[[Append[order, First[order]]]]], Red, Point[pts]}]

data = Table[Sin[x] + 0.3 Sin[7 x] + RandomReal[0.1], {x, 0, 20, 0.05}];
peaks = FindPeaks[data, 3, 0, 0.5];
ListLinePlot[data, Epilog -> {Red, PointSize[Large], Point[peaks]}]

data = Table[{x, 2 x^2 + 3 x + RandomReal[0.1]}, {x, 0, 5, 0.1}];
FindFormula[data, x]
FindFormula[data, x, 3, All]

